types:
pub struct SlotDecl
{ pub name: String, pub render: String, pub props: String }
pub struct EntryBody
{
    pub view: String, pub instance: String, pub api: String, pub version:
    String, pub schema: String, pub render: String, pub bundle: String, pub
    bundle_ref: String, pub parts: Vec<(String, String)>, pub needs:
    Vec<String>, pub place: String, pub data: Vec<String>, pub tries:
    Vec<String>, pub streams: Vec<String>, pub props: String, pub
    props_fields: Vec<(String, String)>, pub state: String, pub slots:
    Vec<SlotDecl>, pub speaks: Vec<String>, pub hears: Vec<String>, pub
    supersedes: Option<String>, pub until: Option<u64>, pub label: String,
} pub struct Signed { pub body: EntryBody, pub node: String, pub sig: String }
pub struct Holder { pub node: String, pub sig: String, pub lease_until: u64 }
pub struct Entry { pub body: EntryBody, pub holders: Vec<Holder> }
pub struct Tree { pub seq: u64, pub entries: Vec<Entry> }
pub struct Complaint
{ pub view: String, pub bundle: String, pub holder: String, pub why: String }
